function pingPong(src, dl, dr, fb) {
  for (let i = 0; i < N; i++) {
    if (i >= dl) src.l[i] += src.l[i - dl] * fb;
    if (i >= dr) src.r[i] += src.r[i - dr] * fb;
  }
}
pingPong(arpBus, Math.round(BEAT * 0.75 * SR), Math.round(BEAT * 0.5 * SR), 0.38);
for (let i = 0; i < N; i++) {
  music.l[i] += arpBus.l[i];
  music.r[i] += arpBus.r[i];
}

