const page = await browser.getPage("wsq0bo-player");
const out = { layouts: [] };
const sizes = [[1600, 900], [1280, 800], [800, 1000], [2400, 800], [390, 844], [1920, 1080]];
for (const [w, h] of sizes) {
  await page.setViewportSize({ width: w, height: h });
  await page.goto("http://127.0.0.1:4877/?p=" + Date.now());
  await page.waitForFunction(() => document.querySelector("video").readyState >= 1, null, { timeout: 30000 });
  const r = await page.evaluate(() => {
    const v = document.querySelector("video");
    const b = v.getBoundingClientRect();
    const cs = getComputedStyle(v);
    return {
      vp: [innerWidth, innerHeight],
      box: [+b.left.toFixed(2), +b.top.toFixed(2), +b.width.toFixed(2), +b.height.toFixed(2)],
      ratio: +(b.width / b.height).toFixed(4),
      fit: cs.objectFit,
      controls: v.controls,
      headings: document.querySelectorAll("h1,h2,h3,h4,h5,h6").length,
      visibleText: document.body.innerText.trim(),
      scroll: [document.documentElement.scrollWidth, document.documentElement.scrollHeight],
    };
  });
  out.layouts.push(r);
}
await page.setViewportSize({ width: 1600, height: 900 });
await page.goto("http://127.0.0.1:4877/?p=" + Date.now());
await page.waitForFunction(() => document.querySelector("video").readyState >= 3, null, { timeout: 30000 });
await page.click("video");
await page.waitForTimeout(1500);
