await page.waitForTimeout(1500);
const s2 = await page.evaluate(() => { const v = document.querySelector("video"); return { t: v.currentTime, paused: v.paused, muted: v.muted, vol: v.volume }; });
out.play = { s1, s2 };
await page.evaluate(() => { document.querySelector("video").currentTime = 43.5; });
await page.waitForTimeout(1200);
out.seek = await page.evaluate(() => { const v = document.querySelector("video"); return { t: v.currentTime, paused: v.paused, ended: v.ended, seeking: v.seeking }; });
const buf = await page.screenshot();
await saveScreenshot(buf, "wsq0bo-player-end.png");
await page.evaluate(() => { document.querySelector("video").currentTime = 12; });
await page.waitForTimeout(800);
await saveScreenshot(await page.screenshot(), "wsq0bo-player-mid.png");
await page.waitForFunction(() => document.querySelector("video").ended, null, { timeout: 5000 }).catch(() => {});
out.title = await page.title();
console.log(JSON.stringify(out));
